export const activeElementOf = (node) => {
    const root = node.getRootNode();
    return root.activeElement !== undefined ? root.activeElement : document.activeElement;
};
export const deepActiveElement = () => {
    let active = document.activeElement;
    while (active?.shadowRoot?.activeElement)
        active = active.shadowRoot.activeElement;
    return active;
};
const isTabStop = (element) => element.tabIndex !== undefined &&
    element.tabIndex >= 0 &&
    !element.matches(":disabled, [inert] *, [inert]") &&
    element.getClientRects().length > 0;
export const tabStops = (container) => {
    const found = [];
    const visit = (element) => {
        const slot = element;
        if (element.localName === "slot" && typeof slot.assignedElements === "function") {
            const assigned = slot.assignedElements({ flatten: true });
            (assigned.length ? assigned : Array.from(element.children)).forEach(visit);
            return;
        }
        if (isTabStop(element))
            found.push(element);
        Array.from((element.shadowRoot ?? element).children).forEach(visit);
    };
    Array.from(container.children).forEach(visit);
    return found;
};
export const wrapTab = (container, event) => {
    if (event.key !== "Tab" || event.defaultPrevented)
        return;
    const stops = tabStops(container);
    const active = deepActiveElement();
    const target = !stops.length
        ? container
        : event.shiftKey && (active === stops[0] || !stops.includes(active))
            ? stops[stops.length - 1]
            : !event.shiftKey && active === stops[stops.length - 1]
                ? stops[0]
                : null;
    if (!target)
        return;
    event.preventDefault();
    target.focus();
};
